# nginx — HTTP'yi kalıcı olarak HTTPS'e yönlendir + HSTS
server {
    listen 80;
    server_name shop.example.com;
    return 301 https://$host$request_uri;
}
server {
    listen 443 ssl http2;
    server_name shop.example.com;
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains; preload" always;
    # ssl_certificate /etc/letsencrypt/live/shop.example.com/fullchain.pem;   # certbot --nginx -d shop.example.com
}

// AI botları JavaScript çalıştırmaz; https://shop.example.com/urun/filtre-klasik ilk HTML'de içerik döndürmeli.
// Next.js (App Router) — sayfayı Server Component olarak render edin:
// app/urun/[slug]/page.tsx
export const revalidate = 3600; // ISR: saatte bir statik yeniden üretim

export default async function ProductPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const product = await getProduct(slug); // sunucuda veri çek (useEffect + fetch DEĞİL)
  return (
    <article>
      <h1>{product.name}</h1>
      <p>{product.summary}</p>
      <ProductSpecsTable specs={product.specs} />
    </article>
  );
}

